### parser.js
--- a/parser.js
+++ b/parser.js
@@ -1,3 +1,6 @@
 export function parseCode(value) {
+  if (typeof value !== 'string' || !/^[0-9]{1,4}$/.test(value)) {
+    throw new Error('Invalid code');
+  }
   return Number(value);
 }

### parser.test.js
--- a/parser.test.js
+++ b/parser.test.js
@@ -0,0 +1,4 @@
+import { strict as assert } from 'node:assert';
+import { parseCode } from './parser.js';
+for (const [input, expected] of [['0', 0], ['007', 7], ['9999', 9999]]) assert.equal(parseCode(input), expected);
+for (const input of ['', 'abc', '-1', '1.5', ' 1', '1 ', '12345', null, 12]) assert.throws(() => parseCode(input), /Invalid code/);

